public class FaultInjectingNioHandler {
    private final Selector selector;
    private final double failureRate;
    private final Random random = new Random();

    public FaultInjectingNioHandler(Selector selector, double failureRate) {
        this.selector = selector;
        this.failureRate = failureRate;
    }

    public void processIoOperations() throws IOException {
        int readyChannels = selector.select(1000);
        if (readyChannels == 0) return;

        Set<SelectionKey> selectedKeys = selector.selectedKeys();
        Iterator<SelectionKey> keyIterator = selectedKeys.iterator();

        while (keyIterator.hasNext()) {
            SelectionKey key = keyIterator.next();
            keyIterator.remove();

            try {
                if (random.nextDouble() < failureRate) {
                    throw new IOException("Chaos Engineering: Simulated IO Subsystem Failure");
                }

                if (key.isReadable()) {
                    SocketChannel channel = (SocketChannel) key.channel();
                    ByteBuffer buffer = ByteBuffer.allocate(1024);
                    int bytesRead = channel.read(buffer);
                    if (bytesRead == -1) {
                        channel.close();
                    }
                }
            } catch (IOException e) {
                // Handle graceful degradation and resource cleanup
                handleIoException(key, e);
            }
        }
    }

    private void handleIoException(SelectionKey key, IOException e) {
        try {
            key.channel().close();
        } catch (IOException ignored) {}
        key.cancel();
    }
}
